  if (contentType.includes("application/json")) {
    return response.json();
  }

  return response.text();
}

function createApiError(response, body) {
  const code =
    body && typeof body === "object" && "error" in body
      ? String(body.error)
      : null;
  const message =
    (code && ERROR_MESSAGES[code]) ??
    (typeof body === "string" && body.trim() !== "" ? body : null) ??
    `Failed to load comments: ${response.status}`;

  const error = new Error(message);
  error.name = "ApiError";
  error.status = response.status;
  error.body = body;
  return error;
}

export async function getComments(slug, { signal } = {}) {
  const response = await fetch(
    `/api/articles/${encodeURIComponent(slug)}/comments`,
    { signal },
  );
  const body = await readResponseBody(response);

  if (!response.ok) {
    throw createApiError(response, body);
  }

  return body.comments;
}

import { useEffect, useState } from "react";
import { getComments } from "./api";
import CommentRow from "./CommentRow";

function createLoadingState() {
  return {
    comments: [],
    error: null,
    isLoading: true,
  };
}

function createSuccessState(comments) {
  return {
    comments,
    error: null,
    isLoading: false,
  };
}

function createErrorState(error) {
  return {
    comments: [],
    error,
    isLoading: false,
  };
}

function CommentFeed({ slug }) {
  const [state, setState] = useState(createLoadingState);

  useEffect(() => {
    let active = true;
    const controller = new AbortController();

    setState(createLoadingState());

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        if (!active) {
          return;
        }

        setState(createSuccessState(comments));
      })
      .catch((error) => {
        if (!active || error?.name === "AbortError") {
          return;
        }

        setState(
          createErrorState(error?.message ?? "Failed to load comments"),
        );
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [slug]);

  const { comments, error, isLoading } = state;

  if (isLoading) {
    return <p className="loading">Loading comments...</p>;
  }

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

